let csrf='',content,version=0,page=0,total=0,dirty=false;
const $=s=>document.querySelector(s),notice=text=>$('#notice').textContent=text;
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json','X-CSRF-Token':csrf,...options.headers}});const data=await r.json();if(r.status===401){$('#login').hidden=false;$('#workspace').hidden=true;$('#logout').hidden=true;}if(!r.ok)throw new Error(data.error||'操作失敗');return data;}
function element(tag,text,cls){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;}
async function start(){const session=await api('/api/admin/session');csrf=session.csrf;$('#login').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;$('#page-title').textContent='客戶留言';await loadMessages();}
$('#login-form').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:new FormData(e.currentTarget).get('password')})});e.target.reset();notice('');await start();}catch(err){notice(err.message)}finally{button.disabled=false}};
$('#logout').onclick=async()=>{if(dirty&&!confirm('尚有未儲存的內容，確定登出？'))return;try{await api('/api/admin/logout',{method:'POST',body:'{}'});location.reload()}catch(e){notice(e.message)}};
async function loadMessages(){const data=await api('/api/admin/messages?page='+page);total=data.total;$('#message-count').textContent=`共 ${total} 則查詢`;$('#messages').replaceChildren();for(const m of data.messages){const card=element('article',undefined,'message'),head=element('div',undefined,'message-head'),who=element('div');who.append(element('h3',m.name+(m.company?' · '+m.company:'')),element('p',new Date(m.created_at*1000).toLocaleString('zh-HK',{timeZone:'Asia/Hong_Kong'})+' · '+m.service,'meta'));const select=element('select');select.setAttribute('aria-label','留言處理狀態');for(const [v,t]of [['new','待處理'],['progress','跟進中'],['done','已完成']]){const o=element('option',t);o.value=v;select.append(o)}select.value=m.status;select.onchange=async()=>{select.disabled=true;try{await api('/api/admin/messages/'+encodeURIComponent(m.id),{method:'PATCH',body:JSON.stringify({status:select.value})});m.status=select.value;notice('狀態已更新')}catch(e){select.value=m.status;notice(e.message)}finally{select.disabled=false}};head.append(who,select);const email=element('a',m.email);email.href='mailto:'+encodeURIComponent(m.email);card.append(head,email,element('div',m.message,'message-body'));$('#messages').append(card)}if(!data.messages.length)$('#messages').append(element('p','暫時沒有客戶留言。','empty'));$('#page').textContent=`第 ${page+1} 頁`;$('#prev').disabled=page===0;$('#next').disabled=(page+1)*50>=total;}
function field(parent,label,value,onchange){const l=element('label',label),input=element('textarea');input.value=value;input.maxLength=6000;input.oninput=()=>{onchange(input.value);dirty=true};l.append(input);parent.append(l);}
function renderEditor(){const root=$('#editor');root.replaceChildren();const groups=[['頁面中英文文案',content.text],['服務介紹',content.services],['企業社會責任',content.csr]];for(const [title,items]of groups){const section=element('details');section.open=title==='頁面中英文文案';section.append(element('summary',title));items.forEach((item,i)=>{const card=element('article',undefined,'edit-card');card.dataset.search=JSON.stringify(item).toLowerCase();card.append(element('small',title+' / '+(i+1)));const grid=element('div',undefined,'edit-grid');function walk(obj,path=[]){for(const [key,value]of Object.entries(obj)){if(key==='id')continue;const next=[...path,key];if(typeof value==='string')field(grid,({zh:'繁體中文',en:'English',desc:'介紹',tag:'標籤',tags:'特色',title:'標題',items:'重點',0:'中文',1:'English'}[key]||key)+(path.length?' · '+path.join(' / '):''),value,v=>{let target=item;next.slice(0,-1).forEach(k=>target=target[k]);target[next.at(-1)]=v;card.dataset.search=JSON.stringify(item).toLowerCase()});else walk(value,next)}}walk(item);card.append(grid);section.append(card)});root.append(section)}}
async function showContent(){if(!content){const data=await api('/api/content');content=data.content;version=data.version;renderEditor()}$('#messages-panel').hidden=true;$('#content-panel').hidden=false;$('#page-title').textContent='網站內容';$('#messages-tab').classList.remove('active');$('#content-tab').classList.add('active');}
$('#content-tab').onclick=()=>showContent().catch(e=>notice(e.message));$('#messages-tab').onclick=()=>{$('#content-panel').hidden=true;$('#messages-panel').hidden=false;$('#page-title').textContent='客戶留言';$('#messages-tab').classList.add('active');$('#content-tab').classList.remove('active')};
$('#save').onclick=async()=>{const button=$('#save');button.disabled=true;try{const data=await api('/api/admin/content',{method:'PUT',body:JSON.stringify({content,version})});version=data.version;dirty=false;notice('已儲存並發布。重新開啟官網即可查看最新內容。')}catch(e){notice(e.message)}finally{button.disabled=false}};
$('#search').oninput=e=>{const query=e.target.value.toLowerCase();document.querySelectorAll('.edit-card').forEach(card=>card.hidden=!card.dataset.search.includes(query));if(query)document.querySelectorAll('details').forEach(el=>el.open=true)};
$('#refresh').onclick=()=>loadMessages().catch(e=>notice(e.message));$('#prev').onclick=()=>{page--;loadMessages().catch(e=>notice(e.message))};$('#next').onclick=()=>{page++;loadMessages().catch(e=>notice(e.message))};
addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});start().catch(e=>{if(e.message!=='請先登入。')notice(e.message)});
